import javax.swing.*;
import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.Supplier;

/** Held-out ecological trials of sampled living genomes against their own founders. */
public final class EvolutionStudyPanel extends JPanel {
    public record Pair(String name,Simulation.Genome current,Simulation.Genome founder){}
    private final Supplier<Simulation> source;
    private final JTextArea report=new JTextArea("Sample living descendants across each role, including different families where available. Trials run complete seasonal cycles with reproduction enabled, under both background-hunter conditions. A focal hunter is retained when other hunters are absent.\n\nResults apply to the sampled genomes and environments; selection of currently living genomes introduces survivor bias.");
    private final JSpinner samples=new JSpinner(new SpinnerNumberModel(3,1,12,1)),trials=new JSpinner(new SpinnerNumberModel(3,1,20,1)),seconds=new JSpinner(new SpinnerNumberModel(120,120,86400,120));
    private final JTextField seed=new JTextField("900001",12);
    private SwingWorker<String,String> worker;
    private final java.util.concurrent.atomic.AtomicBoolean stop=new java.util.concurrent.atomic.AtomicBoolean();
    private static final String HEADER="name,role,condition,seed,genome,meals,survival_seconds,efficiency,offspring_hatched,lineage_descendant_births";
    public EvolutionStudyPanel(Supplier<Simulation> source){super(new BorderLayout(12,12));this.source=source;setBorder(BorderFactory.createEmptyBorder(16,16,16,16));JPanel form=new JPanel(new GridLayout(0,4,8,8));for(Object[] f:new Object[][]{{"Sampled genomes / role",samples},{"Held-out seeds",trials},{"Seconds / trial",seconds},{"First held-out seed",seed}}){form.add(new JLabel((String)f[0]));form.add((JComponent)f[1]);UiTheme.tip((JComponent)f[1],"Configure "+f[0]+"; use fresh seeds not used for selecting these genomes.");}JButton run=new JButton("Run population study"),cancel=new JButton("Cancel"),save=new JButton("Save report…");UiTheme.tip(run,"Capture representative living descendants and their matching founder genomes, then compare both in fresh ecological worlds.");UiTheme.tip(cancel,"Stop the study; keep completed trial rows visible.");UiTheme.tip(save,"Save the visible report, including completed rows from cancelled studies.");form.add(run);form.add(cancel);form.add(save);add(form,BorderLayout.NORTH);report.setEditable(false);report.setLineWrap(true);report.setWrapStyleWord(true);report.setFont(new Font(Font.MONOSPACED,Font.PLAIN,12));add(new JScrollPane(report));cancel.setEnabled(false);
        run.addActionListener(e->{try{for(JSpinner s:new JSpinner[]{samples,trials,seconds})s.commitEdit();Simulation live=source.get();int count=((Number)samples.getValue()).intValue(),n=((Number)trials.getValue()).intValue(),duration=((Number)seconds.getValue()).intValue();long first=Long.parseLong(seed.getText().trim());Math.addExact(first,n-1);if(duration<4*live.config.seasonSeconds)throw new IllegalArgumentException("Use at least one complete seasonal cycle ("+(4*live.config.seasonSeconds)+" seconds).");List<Pair> pairs=sample(live,count);if(pairs.isEmpty())throw new IllegalArgumentException("No sampled living genomes have recorded founders.");WorldConfig settings=live.settings();if(settings.hunterLimit==0)throw new IllegalArgumentException("Enable hunter capacity to test both background-hunter conditions.");java.nio.file.Path output=java.nio.file.Path.of("exports","study-"+System.currentTimeMillis());stop.set(false);run.setEnabled(false);cancel.setEnabled(true);report.setText("Held-out ecological evaluation; reproduction enabled. Source seed: "+(live.seedKnown?live.seed:"unrecorded")+"\nOutput: "+output.toAbsolutePath()+"\n"+HEADER+"\n");
            worker=new SwingWorker<>(){protected String doInBackground()throws Exception{java.nio.file.Files.createDirectories(output);Properties metadata=settings.properties();metadata.setProperty("firstHeldOutSeed",Long.toString(first));metadata.setProperty("trials",Integer.toString(n));metadata.setProperty("secondsPerTrial",Integer.toString(duration));metadata.setProperty("sampling","Living clans, stratified; survivors only. Focal hunter retained without rivals.");try(var w=java.nio.file.Files.newBufferedWriter(output.resolve("manifest.properties"))){metadata.store(w,"Reproduction-enabled founder comparison");}for(int k=0;k<pairs.size();k++){BrainIO.write(output.resolve("pair-"+k+"-current.brain"),pairs.get(k).current());BrainIO.write(output.resolve("pair-"+k+"-founder.brain"),pairs.get(k).founder());}StringBuilder rows=new StringBuilder();try(java.io.PrintWriter csv=new java.io.PrintWriter(java.nio.file.Files.newBufferedWriter(output.resolve("trials.csv")))){csv.println(HEADER);csv.flush();for(Pair pair:pairs)for(boolean hunters:new boolean[]{false,true})for(int i=0;i<n;i++)for(boolean ancestor:new boolean[]{false,true}){if(stop.get()||isCancelled())throw new java.util.concurrent.CancellationException();String row=evaluate(pair,ancestor,hunters,first+i,duration,settings,()->stop.get()||isCancelled());csv.print(row);csv.flush();if(csv.checkError())throw new java.io.IOException("Could not write trial CSV");rows.append(row);publish(row);}}return rows.toString();}protected void process(List<String> chunks){for(String row:chunks)report.append(row);}protected void done(){run.setEnabled(true);cancel.setEnabled(false);try{get();report.append("\nCompleted. Compare paired rows; these samples do not prove improvement across the entire population.\n");}catch(java.util.concurrent.CancellationException ex){report.append("\nCancelled; completed rows retained.\n");}catch(Exception ex){report.append(stop.get()?"\nCancelled; completed rows remain in trials.csv.\n":"\nFailed: "+ex+"\n");}}};worker.execute();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Population study",JOptionPane.ERROR_MESSAGE);}});
        cancel.addActionListener(e->{stop.set(true);cancel.setEnabled(false);});save.addActionListener(e->{JFileChooser c=new JFileChooser();c.setSelectedFile(new java.io.File("evolution-study.txt"));if(c.showSaveDialog(this)==JFileChooser.APPROVE_OPTION){if(c.getSelectedFile().exists()&&JOptionPane.showConfirmDialog(this,"Replace this report?","Report",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{java.nio.file.Files.writeString(c.getSelectedFile().toPath(),report.getText());}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}});UiTheme.apply(this);
    }
    public static List<Pair> sample(Simulation s,int count){List<Pair> result=new ArrayList<>();for(var role:Simulation.Species.values()){var lives=s.creatures.stream().filter(c->c.alive&&c.species==role&&s.founders.containsKey(c.rootId)).sorted(Comparator.comparingInt(c->c.id)).toList();TreeMap<Integer,List<Simulation.Creature>> clans=new TreeMap<>();for(var c:lives)clans.computeIfAbsent(c.rootId,k->new ArrayList<>()).add(c);List<List<Simulation.Creature>> families=new ArrayList<>(clans.values());LinkedHashSet<Simulation.Creature> chosen=new LinkedHashSet<>();int n=Math.min(count,families.size());for(int i=0;i<n;i++){var family=families.get(i*families.size()/n);chosen.add(family.get(family.size()/2));}for(int i=0;chosen.size()<Math.min(count,lives.size())&&i<lives.size();i++)chosen.add(lives.get(i));for(var c:chosen)result.add(new Pair(c.name,c.genome(),s.founders.get(c.rootId)));}return List.copyOf(result);}
    public static String evaluate(Pair pair,boolean ancestor,boolean hunters,long seed,int duration,WorldConfig settings,java.util.function.BooleanSupplier cancelled){WorldConfig c=settings.copy();c.mode=Simulation.Mode.CONTINUOUS;c.pauseAtGenerationEnd=false;c.hunters=hunters;c.initialHunters=hunters?Math.max(1,Math.min(c.initialHunters,c.hunterLimit)):0;Simulation s=new Simulation(c,seed);Simulation.Creature focal=s.prepareTrial(ancestor?pair.founder:pair.current,seed);s.reproductionEnabled=true;if(hunters)s.addTrialHunters(c.initialHunters);int root=focal.rootId;double survived=0;for(int i=0;i<duration*60;i++){if(i%60==0&&cancelled.getAsBoolean())throw new java.util.concurrent.CancellationException();s.step();if(focal.alive)survived=focal.age/60.0;}long descendants=s.lineageBirths(root);return String.format(Locale.US,"%s,%s,%s,%d,%s,%d,%.3f,%.6f,%d,%d%n",pair.name,focal.species,hunters?"other-hunters-on":"other-hunters-off",seed,ancestor?"founder":"descendant",focal.eaten,focal.age/60.0,focal.spent==0?0:focal.gained/focal.spent,focal.children,descendants);}
}
